<body>
<textarea id="lolcrraw" style="display:none;position:absolute;left:-9999px">$1</textarea>
<div id="lolcrwin">
  <div id="lolcrhead">
    <svg id="lolcrsigil" width="34" height="34" viewBox="0 0 28 28"></svg>
    <div id="lolcrhdtxt">
      <div id="lolcrtitle">CRAFTING RESULT</div>
      <div id="lolcrnm">—</div>
      <div id="lolcrsubnm">—</div>
    </div>
    <div id="lolcrqualbadge">—</div>
  </div>
  <div id="lolcrbody"></div>
  <div id="lolcrfoot">RUNETERRA FORGE</div>
</div>
<script>
(function(){
  function g(id){return document.getElementById(id);}
  function esc(v){if(v==null)return '';return String(v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}

  var rawEl=g('lolcrraw'); if(!rawEl)return;
  var raw=(rawEl.value||'').replace(/<\/?LOL_CRAFT_RESULT>/gi,'').trim();
  var d={}; try{d=JSON.parse(raw);}catch(e){}
  var TH=(d.lang==='th');

  var RC={
    demacia:'#4A70B0',noxus:'#9B2020',freljord:'#5FA8C8',ionia:'#9870C0',
    piltover:'#D4A830',zaun:'#4A8A60',shurima:'#C8A84B',ixtal:'#3A8A50',
    targon:'#7A8EC8',camavor:'#A83848',shadow_isles:'#2A8060',
    bilgewater:'#C87840',bandle:'#D4B870',void:'#8A4AC8'
  };
  var acc=d.theme_color||RC[d.region]||'#C89B3C';

  var QUAL={
    excellent:{c:'#ffd700',g:'rgba(255,215,0,.5)', ic:'✦',lbl_en:'EXCELLENT', lbl_th:'ยอดเยี่ยม'},
    good:     {c:'#50d870',g:'rgba(80,216,112,.4)',ic:'◆',lbl_en:'GOOD',      lbl_th:'ดี'},
    ok:       {c:'#c89030',g:'rgba(200,144,48,.4)',ic:'◈',lbl_en:'OK',        lbl_th:'พอใช้'},
    bad:      {c:'#c85030',g:'rgba(200,80,48,.4)', ic:'▲',lbl_en:'BAD',       lbl_th:'แย่'},
    failed:   {c:'#a03030',g:'rgba(160,48,48,.5)', ic:'✗',lbl_en:'FAILED',    lbl_th:'ล้มเหลว'}
  };

  var qkey=(d.quality||'ok').toLowerCase();
  var Q=QUAL[qkey]||QUAL.ok;
  var isFailed=(qkey==='failed');

  function hexRgb(h){
    var s=String(h||'').replace('#','');
    if(s.length===3)s=s[0]+s[0]+s[1]+s[1]+s[2]+s[2];
    var n=parseInt(s,16)||0xC89B3C;
    return ((n>>16)&255)+','+((n>>8)&255)+','+(n&255);
  }

  var win=g('lolcrwin'); if(!win)return;
  var rgb=hexRgb(acc);
  win.style.setProperty('--acc',acc);
  win.style.setProperty('--abg','rgba('+rgb+',.12)');
  win.style.setProperty('--abd','rgba('+rgb+',.28)');
  win.style.setProperty('--bd','rgba('+rgb+',.25)');

  function sigilPath(r){
    var c=acc;
    var p={
      demacia:'<polygon points="14,2 22,10 22,24 6,24 6,10" fill="none" stroke="'+c+'" stroke-width="1.5"/><line x1="14" y1="2" x2="14" y2="24" stroke="'+c+'" stroke-width="1"/><line x1="6" y1="14" x2="22" y2="14" stroke="'+c+'" stroke-width="1"/>',
      noxus:'<polygon points="14,3 24,25 4,25" fill="none" stroke="'+c+'" stroke-width="1.5"/><polygon points="14,10 20,22 8,22" fill="'+c+'" opacity=".3"/>',
      freljord:'<line x1="14" y1="2" x2="14" y2="26" stroke="'+c+'" stroke-width="1.5"/><line x1="2" y1="14" x2="26" y2="14" stroke="'+c+'" stroke-width="1.5"/><circle cx="14" cy="14" r="3" fill="'+c+'"/>',
      ionia:'<circle cx="14" cy="10" r="4" fill="'+c+'"/><circle cx="14" cy="18" r="4" fill="none" stroke="'+c+'" stroke-width="1.5"/><circle cx="14" cy="14" r="9" fill="none" stroke="'+c+'" stroke-width="1"/>',
      piltover:'<circle cx="14" cy="14" r="9" fill="none" stroke="'+c+'" stroke-width="1.5"/><circle cx="14" cy="14" r="3" fill="'+c+'"/>',
      zaun:'<rect x="9" y="3" width="10" height="14" rx="5" fill="none" stroke="'+c+'" stroke-width="1.5"/><line x1="8" y1="22" x2="20" y2="22" stroke="'+c+'" stroke-width="1.5"/>',
      shurima:'<circle cx="14" cy="14" r="9" fill="none" stroke="'+c+'" stroke-width="1"/><polygon points="14,5 16.5,11.5 23,11.5 17.5,15.5 19.5,22 14,18 8.5,22 10.5,15.5 5,11.5 11.5,11.5" fill="'+c+'" opacity=".6"/>',
      ixtal:'<circle cx="14" cy="14" r="6" fill="none" stroke="'+c+'" stroke-width="1.5"/><ellipse cx="14" cy="7" rx="3" ry="5" fill="'+c+'" opacity=".5"/><ellipse cx="7" cy="14" rx="5" ry="3" fill="'+c+'" opacity=".5"/>',
      targon:'<polygon points="14,2 22,24 6,24" fill="none" stroke="'+c+'" stroke-width="1.5"/><circle cx="14" cy="8" r="2.5" fill="'+c+'"/>',
      camavor:'<circle cx="14" cy="11" r="7" fill="none" stroke="'+c+'" stroke-width="1.5"/><line x1="14" y1="18" x2="14" y2="26" stroke="'+c+'" stroke-width="1.5"/>',
      shadow_isles:'<circle cx="14" cy="14" r="5" fill="none" stroke="'+c+'" stroke-width="1.5"/><circle cx="7" cy="9" r="2.5" fill="none" stroke="'+c+'" stroke-width="1"/><circle cx="21" cy="9" r="2.5" fill="none" stroke="'+c+'" stroke-width="1"/><circle cx="14" cy="22" r="2.5" fill="none" stroke="'+c+'" stroke-width="1"/>',
      bilgewater:'<line x1="14" y1="3" x2="14" y2="25" stroke="'+c+'" stroke-width="1.5"/><line x1="6" y1="10" x2="22" y2="10" stroke="'+c+'" stroke-width="1.5"/>',
      bandle:'<rect x="8" y="12" width="12" height="12" rx="2" fill="none" stroke="'+c+'" stroke-width="1.2"/><polygon points="14,2 24,12 4,12" fill="none" stroke="'+c+'" stroke-width="1.5"/>',
      void:'<ellipse cx="14" cy="14" rx="10" ry="10" fill="none" stroke="'+c+'" stroke-width="1.5"/><circle cx="14" cy="14" r="2.5" fill="'+c+'"/>'
    };
    var def='<circle cx="14" cy="14" r="9" fill="none" stroke="'+c+'" stroke-width="1.2"/><line x1="14" y1="5" x2="14" y2="23" stroke="'+c+'" stroke-width="1"/><line x1="5" y1="14" x2="23" y2="14" stroke="'+c+'" stroke-width="1"/>';
    return p[r]||def;
  }

  function typeIcon(t){
    var m={
      'Equipment':'⚒','Weapon':'⚔','Armor':'🛡',
      'Material':'◼','Consumable':'⬡','Key':'⬟','Catalyst':'◈','Other':'◇'
    };
    return m[t]||'◇';
  }

  function qLabel(Q){return TH?Q.lbl_th:Q.lbl_en;}

  // ─── HEADER ───
  var sg=g('lolcrsigil'); if(sg)sg.innerHTML=sigilPath(d.region);
  var nm=g('lolcrnm');   if(nm)nm.textContent=d.character||'—';
  var snm=g('lolcrsubnm'); if(snm)snm.textContent=d.region||'—';
  var qb=g('lolcrqualbadge');
  if(qb){
    qb.textContent=Q.ic+' '+qLabel(Q);
    qb.style.color=Q.c;
    qb.style.borderColor=Q.c+'55';
    qb.style.background='rgba('+hexRgb(Q.c)+',.1)';
    qb.style.boxShadow='0 0 10px '+Q.g;
  }
  var ft=g('lolcrfoot');
  if(ft)ft.textContent=TH?'เตาหลอมแห่งรูนเทอร์รา':'RUNETERRA FORGE';

  // ─── BODY ───
  var body=g('lolcrbody'); if(!body)return;

  var ingredients=Array.isArray(d.ingredients)?d.ingredients:[];
  var chips=ingredients.length
    ?ingredients.map(function(s){return '<div class="lolcr-chip">'+esc(s)+'</div>';}).join('')
    :'<div class="lolcr-chip" style="color:var(--tx3);border-left-color:var(--bg5)">—</div>';

  var intentHtml=d.intent
    ?('<div class="lolcr-sec">'+(TH?'เป้าหมาย':'INTENT')+'</div><div class="lolcr-intent">'+esc(d.intent)+'</div>')
    :'';

  var ingrSec=isFailed
    ?(TH?'ส่วนผสมที่สูญเสีย':'INGREDIENTS CONSUMED')
    :(TH?'ส่วนผสม':'INGREDIENTS');

  var divLbl=isFailed
    ?(TH?'ล้มเหลว':'CRAFTING FAILED')
    :(TH?'ผลลัพธ์':'CRAFTED');

  var resultHtml;
  if(isFailed){
    resultHtml=
      '<div class="lolcr-result" style="border-left-color:#a03030">'+
        '<div class="lolcr-res-top">'+
          '<div class="lolcr-res-ico" style="color:#a04040">'+Q.ic+'</div>'+
          '<div class="lolcr-res-info">'+
            '<div class="lolcr-res-name" style="color:#a04040">'+(TH?'ไม่มีผลลัพธ์':'Nothing produced')+'</div>'+
          '</div>'+
        '</div>'+
        '<div class="lolcr-failed-msg">'+
          (TH?'การคราฟล้มเหลว — ส่วนผสมทั้งหมดถูกสูญเสียไป':'The crafting attempt failed — all ingredients were consumed.')+
        '</div>'+
      '</div>';
  } else {
    var qclr=Q.c;
    var qextra=qkey==='excellent'?' q-excellent':'';
    resultHtml=
      '<div class="lolcr-result'+qextra+'" style="border-left-color:'+qclr+'">'+
        '<div class="lolcr-res-top">'+
          '<div class="lolcr-res-ico" style="color:'+qclr+'">'+typeIcon(d.item_type||'Other')+'</div>'+
          '<div class="lolcr-res-info">'+
            '<div class="lolcr-res-name" style="color:'+qclr+'">'+esc(d.result||'—')+'</div>'+
            (d.item_type?'<div class="lolcr-type-badge">'+esc(d.item_type)+'</div>':'')+
          '</div>'+
        '</div>'+
        (d.desc?'<div class="lolcr-desc">'+esc(d.desc)+'</div>':'')+
      '</div>';
  }

  var notesHtml=d.notes?('<div class="lolcr-notes">'+esc(d.notes)+'</div>'):'';

  body.innerHTML=
    intentHtml+
    '<div class="lolcr-sec">'+ingrSec+'</div>'+
    '<div class="lolcr-chips">'+chips+'</div>'+
    '<div class="lolcr-div">'+
      '<div class="lolcr-div-line"></div>'+
      '<div class="lolcr-div-lbl">'+divLbl+'</div>'+
      '<div class="lolcr-div-line"></div>'+
    '</div>'+
    resultHtml+
    notesHtml;
})();
</script>
